local phase = "new"
local leg = 0
local route = {
  {1143,-840,-126,0},
  {1138,-809,-126,0},
  {1194,-794,-136,0},
  {1324,-840,-136,0},
  {1368,-840,-116,0},
  {1419,-838,-116,0},
  {1476,-797,-116,0},
  {1476,-797,-116,0},
}
local function walk(e,next_leg)
  leg = next_leg; phase = "walking"
  local p = route[leg]
  e.self:SetRunning(true)
  e.self:MoveTo(p[1],p[2],p[3])
end
local function fail()
  if phase == "ended" then return end
  phase = "ended"; eq.stop_all_timers(); eq.signal(113486,3); eq.depop()
end
function event_spawn(e)
  if phase ~= "new" then return end
